"""
        Return a category from its id
    """
def category(id: Any) -> object {
    return ("category! " + id);
}

test_blocks:
test "t0" {
    assert (category("") == "category! ");;
}

test "t1" {
    assert (category("test") == "category! test");;
}

test "t2" {
    assert (category("5") == "category! 5");;
}

test "t3" {
    assert (category('11') == 'category! 11');;
}

test "t4" {
    assert (category('1') == 'category! 1');;
}
